function CheckinScannerView() {
  const [mode, setMode] = useState<'scan' | 'lookup'>('scan')
  const [scanState, setScanState] = useState<'ready' | 'success' | 'error'>('ready')
  const [query, setQuery] = useState('')
  const [checkedIn, setCheckedIn] = useState<string[]>([])
  const attendees = [
    { name: 'Jordan Lee', email: 'jordan@selah.co', ticket: 'General admission', initials: 'JL' },
    { name: 'Mina Park', email: 'mina@arc.studio', ticket: 'Studio circle', initials: 'MP' },
    { name: 'David Okafor', email: 'david@linear.co', ticket: 'General admission', initials: 'DO' },
  ]
  const filtered = attendees.filter((attendee) => attendee.name.toLowerCase().includes(query.toLowerCase()) || attendee.email.toLowerCase().includes(query.toLowerCase()))
  const completeCheckin = (name: string) => {
    setCheckedIn((current) => current.includes(name) ? current : [...current, name])
    setScanState('success')
  }
  return <div className="mx-auto max-w-3xl space-y-5 animate-in px-1 sm:px-4">
    <div className="flex items-center justify-between"><div><div className="eyebrow text-[#a8dfbd]">SELAH STAFF · GATE 01</div><h1 className="mt-2 text-2xl font-medium tracking-tight text-white sm:text-3xl">Check-in scanner</h1><p className="mt-1 text-sm text-zinc-500">The New Perspective · October 24—26</p></div><div className="flex size-10 items-center justify-center rounded-2xl border border-white/[0.08] bg-white/[0.04] text-zinc-400"><Camera className="size-4" /></div></div>
    <div className="flex rounded-2xl border border-white/[0.08] bg-white/[0.025] p-1"><button onClick={() => setMode('scan')} className={`flex flex-1 items-center justify-center gap-2 rounded-xl px-4 py-3 text-xs transition ${mode === 'scan' ? 'bg-white/[0.1] text-white shadow-[0_0_24px_rgba(168,223,189,.07)]' : 'text-zinc-500'}`}><ScanLine className="size-4" /> Scan QR</button><button onClick={() => setMode('lookup')} className={`flex flex-1 items-center justify-center gap-2 rounded-xl px-4 py-3 text-xs transition ${mode === 'lookup' ? 'bg-white/[0.1] text-white shadow-[0_0_24px_rgba(168,223,189,.07)]' : 'text-zinc-500'}`}><UserRound className="size-4" /> Manual lookup</button></div>
    {mode === 'scan' ? <div className="glass-panel overflow-hidden p-5 sm:p-8"><div className="flex items-center justify-between"><div><div className="eyebrow">LIVE CAMERA</div><h2 className="mt-2 text-lg font-medium text-white">Point at an attendee QR code.</h2></div><span className="flex items-center gap-2 rounded-full bg-[#a8dfbd]/10 px-2.5 py-1.5 text-[10px] text-[#a8dfbd]"><span className="size-1.5 animate-pulse rounded-full bg-current" /> Ready</span></div><div className={`relative mx-auto mt-7 aspect-square max-w-[360px] overflow-hidden rounded-[34px] border-2 bg-[radial-gradient(circle_at_50%_45%,rgba(62,99,90,.45),rgba(12,17,17,.98)_67%)] transition duration-500 ${scanState === 'success' ? 'border-[#a8dfbd] shadow-[0_0_55px_rgba(168,223,189,.32)]' : scanState === 'error' ? 'border-[#ee8b83] shadow-[0_0_55px_rgba(238,139,131,.24)]' : 'border-[#a8dfbd]/60 shadow-[0_0_45px_rgba(168,223,189,.14)]'}`}><div className="absolute inset-8 rounded-[24px] border border-white/[0.08]" /><div className={`absolute left-10 right-10 top-1/2 h-px animate-pulse ${scanState === 'success' ? 'bg-[#a8dfbd]' : scanState === 'error' ? 'bg-[#ee8b83]' : 'bg-[#b9e8d3]'}`} /><div className="absolute inset-0 grid place-items-center"><div className="grid size-24 place-items-center rounded-3xl border border-white/[0.08] bg-black/20 backdrop-blur-sm"><QrCode className={`size-11 ${scanState === 'success' ? 'text-[#a8dfbd]' : scanState === 'error' ? 'text-[#ee8b83]' : 'text-zinc-300'}`} /></div></div><div className="absolute bottom-5 left-0 right-0 text-center text-[10px] uppercase tracking-[0.18em] text-white/50">Align QR within frame</div></div>{scanState !== 'ready' && <div className={`mx-auto mt-5 flex max-w-[360px] items-start gap-3 rounded-2xl border p-4 ${scanState === 'success' ? 'border-[#a8dfbd]/20 bg-[#a8dfbd]/10' : 'border-[#ee8b83]/20 bg-[#ee8b83]/10'}`}>{scanState === 'success' ? <Check className="mt-0.5 size-4 text-[#a8dfbd]" /> : <AlertTriangle className="mt-0.5 size-4 text-[#ee8b83]" />}<div><div className={`text-sm font-medium ${scanState === 'success' ? 'text-[#b9e8d3]' : 'text-[#ffb0a8]'}`}>{scanState === 'success' ? 'Check-in successful' : 'Invalid ticket'}</div><div className="mt-1 text-xs text-zinc-400">{scanState === 'success' ? 'Jordan Lee · General admission' : 'This QR code is not valid for this event.'}</div></div></div>}<div className="mt-6 flex gap-3"><button onClick={() => setScanState('success')} className="flex-1 rounded-xl border border-white/[0.08] bg-white/[0.04] px-4 py-3 text-xs text-zinc-300 transition hover:bg-white/[0.08]">Simulate success</button><button onClick={() => setScanState('error')} className="flex-1 rounded-xl border border-white/[0.08] bg-white/[0.04] px-4 py-3 text-xs text-zinc-300 transition hover:bg-white/[0.08]">Simulate error</button></div></div> : <div className="glass-panel p-5 sm:p-6"><div className="eyebrow">NO CAMERA? NO PROBLEM.</div><h2 className="mt-2 text-xl font-medium text-white">Find an attendee manually.</h2><div className="relative mt-5"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-zinc-600" /><input value={query} onChange={(event) => setQuery(event.target.value)} aria-label="Search attendee" placeholder="Search by name or email" className="premium-input pl-10" /></div><div className="mt-4 flex flex-col gap-2">{filtered.map((attendee) => { const done = checkedIn.includes(attendee.name); return <div key={attendee.email} className="flex items-center gap-3 rounded-2xl border border-white/[0.08] bg-white/[0.025] p-3"><div className="grid size-10 place-items-center rounded-full bg-gradient-to-br from-[#c49c70] to-[#e6c9a7] text-xs font-semibold text-[#171413]">{attendee.initials}</div><div className="min-w-0 flex-1"><div className="text-sm text-zinc-200">{attendee.name}</div><div className="mt-1 truncate text-[11px] text-zinc-600">{attendee.email} · {attendee.ticket}</div></div><button onClick={() => completeCheckin(attendee.name)} disabled={done} className={`rounded-full px-3 py-2 text-[10px] font-medium transition ${done ? 'bg-[#a8dfbd]/10 text-[#a8dfbd]' : 'bg-white/[0.08] text-zinc-300 hover:bg-[#a8dfbd]/15 hover:text-[#b9e8d3]'}`}>{done ? 'Checked in' : 'Swipe to check-in'}</button></div> })}</div></div>}
    <div className="flex items-center justify-center gap-2 text-[10px] text-zinc-600"><ShieldCheck className="size-3.5 text-[#a8dfbd]" /> Staff mode · Check-ins sync securely</div>
  </div>
}

